-- Generated executable query. Run with SQLite against indus_weave.db.
-- Paid means positive EARNING components; zero attendance means zero Present days in the payroll month. Deductions are excluded.
WITH paid AS (SELECT emp_id,substr(month_start,1,7) month,SUM(amount) paid_earnings FROM fact_payroll_line WHERE upper(component_type)='EARNING' AND amount>0 GROUP BY emp_id,substr(month_start,1,7)), att AS (SELECT a.emp_id,substr(d.full_date,1,7) month,SUM(a.status='Present') present_days FROM fact_attendance_daily a JOIN dim_date d ON d.date_key=a.date_key GROUP BY a.emp_id,substr(d.full_date,1,7)) SELECT p.emp_id,p.month,p.paid_earnings,COALESCE(a.present_days,0) present_days FROM paid p LEFT JOIN att a ON a.emp_id=p.emp_id AND a.month=p.month WHERE COALESCE(a.present_days,0)=0 ORDER BY p.month,p.emp_id;
